import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const stage=process.argv[2];assert(stage.startsWith('F:/VisibleMedicine/staging/')&&!stage.includes('..'));const prep=json(stage+'/PREPARED.json'),dir=stage+'/atlas/node_modules',saved=stage+'/node_modules.shared',actual=fs.realpathSync(dir);assert.equal(actual,fs.realpathSync(prep.parent+'/node_modules'));assert(fs.lstatSync(dir).isSymbolicLink());assert(!fs.existsSync(saved));fs.renameSync(dir,saved);fs.mkdirSync(dir);const copied=[],linked=[];
function verify(from,to,prefix){for(const e of fs.readdirSync(from,{withFileTypes:true})){assert(!e.isSymbolicLink());const name=prefix+'/'+e.name;if(e.isDirectory())verify(from+'/'+e.name,to+'/'+e.name,name);else{assert.equal(hash(from+'/'+e.name),hash(to+'/'+e.name));copied.push({path:name,bytes:fs.statSync(to+'/'+e.name).size,sha256:hash(to+'/'+e.name)});}}}
for(const e of fs.readdirSync(actual,{withFileTypes:true})){const from=actual+'/'+e.name,to=dir+'/'+e.name;if(['three','three-mesh-bvh'].includes(e.name)){assert(fs.statSync(from).isDirectory());fs.cpSync(from,to,{recursive:true,dereference:false,errorOnExist:true});verify(from,to,e.name);}else if(fs.statSync(from).isDirectory()){fs.symlinkSync(fs.realpathSync(from),to,'junction');assert.equal(fs.realpathSync(to),fs.realpathSync(from));linked.push(e.name);}else{fs.copyFileSync(from,to,fs.constants.COPYFILE_EXCL);assert.equal(hash(from),hash(to));}}
fs.writeFileSync(stage+'/DEPENDENCY_LAYOUT.json',JSON.stringify({at:new Date().toISOString(),source:actual,savedJunction:saved,copied,linked,packageVersionsChanged:false,globalInstallationChanged:false,confinementGuardChanged:false,reason:'Hermetic selection helper requires real Three/BVH source under its own checkout. Exact installed package bytes are copied; the original shared link is preserved, not removed.'},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({files:copied.length,bytes:copied.reduce((n,r)=>n+r.bytes,0),linked:linked.length}));
